import java.util.*;import java.lang.reflect.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import com.project.common.config.MerchantApiJobs;import com.project.system.service.MerchantApiService;
public class ApiNotificationRetryIntegration{public static void main(String[]args)throws Exception{JdbcTemplate db=new JdbcTemplate(new DriverManagerDataSource("jdbc:mysql://127.0.0.1:13306/cc_api_test?useSSL=false&serverTimezone=Asia/Shanghai","root",""));db.update("update campus_api_credential set callback_url=''");Map<String,Object> row=db.queryForMap("select id,merchant_id from campus_api_outbox order by id desc limit 1");db.update("update campus_api_credential set callback_url='https://127.0.0.1/notify' where merchant_id=?",row.get("merchant_id"));MerchantApiJobs jobs=new MerchantApiJobs();Field f=MerchantApiJobs.class.getDeclaredField("db");f.setAccessible(true);f.set(jobs,db);for(int i=0;i<5;i++){db.update("update campus_api_outbox set next_at=NOW() where id=?",row.get("id"));jobs.send();}Map<String,Object> result=db.queryForMap("select status,attempts,last_error from campus_api_outbox where id=?",row.get("id"));if(!"FAILED".equals(result.get("status"))||((Number)result.get("attempts")).intValue()!=5)throw new AssertionError(result.toString());System.out.println("PASS notification retries persist and stop after five attempts");if(!String.valueOf(result.get("last_error")).contains("内网"))throw new AssertionError();System.out.println("PASS private callback blocked before network access");try{MerchantApiService.validateCallback("http://127.0.0.1/notify");throw new AssertionError();}catch(IllegalArgumentException expected){System.out.println("PASS non-HTTPS callback rejected");}db.update("update campus_api_credential set callback_url='' where merchant_id=?",row.get("merchant_id"));}}
